class Solution {
public:
    int countCutAheadAdventurers(
        int n,
        const vector<int>& entryOrder,
        const vector<int>& chamberOrder
    ) {
        if (n <= 1) return 0;

        int maxId = n;
        for (int x : entryOrder) {
            if (x > maxId) maxId = x;
        }

        vector<int> pos(maxId + 1);
        for (int i = 0; i < n; ++i) {
            pos[entryOrder[i]] = i;
        }

        int ans = 0;
        int minPos = n + 1;
        for (int i = n - 1; i >= 0; --i) {
            int p = pos[chamberOrder[i]];
            if (p > minPos) {
                ans++;
            } else {
                minPos = p;
            }
        }

        return ans;
    }
};


class Solution {
public:
    vector<string> manage_recipe_experiments(vector<string> operations) {
        vector<string> history;
        history.push_back("Basic");
        int cur = 0;
        vector<string> ans;

        for (const string& op : operations) {
            if (op.empty()) continue;
            stringstream ss(op);
            string cmd;
            if (!(ss >> cmd)) continue;

            if (cmd == "COOK") {
                string recipe;
                ss >> recipe;
                history.resize(cur + 1);
                history.push_back(recipe);
                cur++;
            } else if (cmd == "UNDO") {
                long long k;
                ss >> k;
                cur = max(0LL, (long long)cur - k);
                ans.push_back(history[cur]);
            } else if (cmd == "REDO") {
                long long k;
                ss >> k;
                cur = min((long long)history.size() - 1, (long long)cur + k);
                ans.push_back(history[cur]);
            } else if (cmd == "ACTIVE") {
                ans.push_back(history[cur]);
            }
        }

        return ans;
    }
};
